import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import TestComponent from './TestComponent';
import SimpleUploadPage from './pages/SimpleUploadPage';
import SimpleDashboard from './pages/SimpleDashboard';
import SimpleResearchInsights from './pages/SimpleResearchInsights';
import SimpleCAMPreview from './pages/SimpleCAMPreview';
import './App.css';

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<SimpleUploadPage />} />
        <Route path="/dashboard" element={<SimpleDashboard />} />
        <Route path="/research" element={<SimpleResearchInsights />} />
        <Route path="/cam-preview" element={<SimpleCAMPreview />} />
        <Route path="/test" element={<TestComponent />} />
      </Routes>
    </Router>
  );
}

export default App;
